<template>
  <Card>
    <CardHeader>
      <CardTitle>General Recruitment</CardTitle>
    </CardHeader>
    <CardContent>
      <NavigationGuard
        :saved-data="processedPassedData"
        :changed-data="processedDataFromForm"
        title="Warning"
        description="You have some unsaved changes on this tab! Save them before switching to another tab."
        confirm-text="Discard Changes"
      />
      <form id="settingsGeneralForm" class="flex flex-col gap-6" @submit="onSubmit">
        <div class="flex items-center justify-between rounded-md border p-4">
          <div class="flex items-center gap-1">
            <label for="enabled" class="text-sm font-medium">Autonomous General Recruitment</label>
            <Popover>
              <PopoverTrigger type="button"><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
              <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                <p class="font-semibold mb-4">Autonomous General Recruitment</p>
                {{ settingsFieldDescriptions.general.enabled }}
              </PopoverContent>
            </Popover>
          </div>
          <Switch id="enabled" :model-value="values.enabled" @update:model-value="(v) => setFieldValue('enabled', v)" />
        </div>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Selling Points"
              name="selling_points"
              :is-required="true"
              :description="settingsFieldDescriptions.general.selling_points"
            >
              <template #default="{ slots }">
                <Textarea id="selling_points" rows="5" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Latest News"
              name="latest_news"
              :is-required="true"
              :description="settingsFieldDescriptions.general.latest_news"
            >
              <template #default="{ slots }">
                <Textarea id="latest_news" rows="4" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Custom Notes"
              name="custom_notes"
              :description="settingsFieldDescriptions.general.custom_notes"
            >
              <template #default="{ slots }">
                <Textarea id="custom_notes" rows="4" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>
          </div>

          <div class="flex flex-col gap-4">
            <FormItemWrapper
              label="Channel Strategy"
              name="channel_strategy"
              :is-required="true"
              :description="settingsFieldDescriptions.general.channel_strategy"
            >
              <template #default="{ slots }">
                <KitFormsSelect
                  id="channel_strategy"
                  :items="channelStrategyOptions"
                  :component-field="slots.componentField"
                />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="Default Urgency Level"
              name="default_urgency_level"
              :is-required="true"
              :description="settingsFieldDescriptions.general.default_urgency_level"
            >
              <template #default="{ slots }">
                <KitFormsSelect
                  id="default_urgency_level"
                  :items="campaignUrgencyOptions"
                  :component-field="slots.componentField"
                />
              </template>
            </FormItemWrapper>

            <FormItemWrapper
              label="QRF Radius (miles)"
              name="qrf_radius_miles"
              :is-required="true"
              :description="settingsFieldDescriptions.general.qrf_radius_miles"
            >
              <template #default="{ slots }">
                <Input id="qrf_radius_miles" type="number" min="1" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>
          </div>
        </div>

        <FormItemWrapper
          label="Inbound Notification Email"
          name="inbound_notification_email"
          :description="settingsFieldDescriptions.general.inbound_notification_email"
        >
          <template #default="{ slots }">
            <Input
              id="inbound_notification_email"
              type="email"
              placeholder="alerts@example.com"
              v-bind="slots.componentField"
            />
          </template>
        </FormItemWrapper>

        <div class="flex justify-end">
          <Button
            type="submit"
            :loading="isUpdateSettingsGeneralLoading"
            :disabled="isEqual(processedDataFromForm, processedPassedData) || isUpdateSettingsGeneralLoading"
          >
            Save General Settings
          </Button>
        </div>
      </form>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { isEqual } from 'lodash';
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import type {
  CampaignUrgency,
  GeneralRecruitmentConfig,
  GetAllSystemSettingsResponse,
  RecruitmentChannelStrategy,
} from '~/client';
import { formSchema } from '~/constants/validationSchemas/recruitmentSettingsGeneral';
import { useUpdateSettingsGeneral } from '~/mutations/system/updateSettingsGeneral';
import { campaignUrgencyOptions } from '~/constants/recruitment/campaignUrgencyConfig';
import { channelStrategyOptions } from '~/constants/recruitment/channelStrategyConfig';
import { settingsFieldDescriptions } from '~/constants/recruitment/settingsFieldDescriptions';

const props = defineProps<{
  settings: GetAllSystemSettingsResponse;
}>();

definePageMeta({
  roles: ['admin'],
});

const { updateSettingsGeneral, isUpdateSettingsGeneralLoading } = useUpdateSettingsGeneral();

const { handleSubmit, values, resetForm, setFieldValue } = useForm({
  validationSchema: formSchema,
  initialValues: {
    enabled: false,
    channel_strategy: undefined,
    selling_points: '',
    latest_news: '',
    custom_notes: '',
    default_urgency_level: undefined,
    qrf_radius_miles: undefined,
    inbound_notification_email: '',
  },
});

function hydrate(config: GeneralRecruitmentConfig) {
  resetForm({
    values: {
      enabled: config.enabled,
      channel_strategy: config.channel_strategy,
      selling_points: config.selling_points,
      latest_news: config.latest_news,
      custom_notes: config.custom_notes,
      default_urgency_level: config.default_urgency_level,
      qrf_radius_miles: config.qrf_radius_miles,
      inbound_notification_email: config.inbound_notification_email ?? '',
    },
  });
}

onMounted(() => hydrate(props.settings.general_recruitment));

const processedPassedData = computed(() => props.settings.general_recruitment);

const processedDataFromForm = computed<GeneralRecruitmentConfig>(() => ({
  enabled: values.enabled ?? false,
  channel_strategy: values.channel_strategy as RecruitmentChannelStrategy,
  selling_points: values.selling_points ?? '',
  latest_news: values.latest_news ?? '',
  custom_notes: values.custom_notes ?? '',
  default_urgency_level: values.default_urgency_level as CampaignUrgency,
  qrf_radius_miles: toNumberOrNull(values.qrf_radius_miles) ?? 0,
  inbound_notification_email: values.inbound_notification_email?.trim()
    ? values.inbound_notification_email.trim()
    : null,
}));

const onSubmit = handleSubmit(async (formValues) => {
  await updateSettingsGeneral(formValues as GeneralRecruitmentConfig);
  hydrate(formValues as GeneralRecruitmentConfig);
});
</script>
