import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { campaignUrgencyValues } from '~/constants/recruitment/campaignUrgencyConfig';
import { channelStrategyValues } from '~/constants/recruitment/channelStrategyConfig';
import { positiveIntPreset } from './utils';

export const schemaObject = {
  enabled: z.boolean({ message: 'Enabled flag is required' }),
  channel_strategy: z.enum(channelStrategyValues, {
    message: 'Channel strategy is required',
  }),
  selling_points: z
    .string({ message: 'Selling points is required' })
    .trim()
    .nonempty({ message: 'Selling points is required' })
    .max(5000, { message: 'Must be at most 5000 characters' }),
  latest_news: z
    .string({ message: 'Latest news is required' })
    .trim()
    .nonempty({ message: 'Latest news is required' })
    .max(5000, { message: 'Must be at most 5000 characters' }),
  custom_notes: z.string().trim().max(5000, { message: 'Must be at most 5000 characters' }),
  default_urgency_level: z.enum(campaignUrgencyValues, {
    message: 'Default urgency is required',
  }),
  qrf_radius_miles: positiveIntPreset({
    max: 3000,
    requiredMessage: 'QRF radius is required',
    maxMessage: 'Must be at most 3000',
    integerMessage: 'Must be a whole number',
  }),
  inbound_notification_email: z
    .string()
    .trim()
    .nullable()
    .transform((v) => v || null)
    .pipe(
      z
        .string()
        .email({ message: 'Enter a valid email address' })
        .max(255, { message: 'Must be at most 255 characters' })
        .nullable()
    ),
};

export const formSchema = toTypedSchema(z.object(schemaObject));
