import { updateGeneralRecruitmentSettings, type GeneralRecruitmentConfig } from '~/client';

export const useUpdateSettingsGeneral = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: GeneralRecruitmentConfig): Promise<GeneralRecruitmentConfig> =>
      updateGeneralRecruitmentSettings({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: () => {
      queryCache.invalidateQueries({ key: ['system-settings'] });
      showToastSuccess('General settings updated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    updateSettingsGeneral: mutateAsync,
    isUpdateSettingsGeneralLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
